// Normaliza lo que manda ManyChat (External Request) a un formato único,
// igual que hacía "Edit Fields1" con Telegram en el demo.
// Acepta dos formatos de body:
//  A) campos sueltos: subscriber_id, nombre, apellido, telefono, texto, adjunto_url, tipo, bot_activo, ultima_interaccion
//  B) la variable "Full Contact Data" de ManyChat: {"contacto": {{Full Contact Data}}} (o el objeto directo)
const crudo = $('Webhook ManyChat').first().json.body || {};
const contacto = crudo.contacto && typeof crudo.contacto === 'object'
  ? crudo.contacto
  : (crudo.custom_fields && crudo.id !== undefined ? crudo : null);
const body = contacto
  ? {
    subscriber_id: contacto.id,
    nombre: contacto.first_name,
    apellido: contacto.last_name,
    telefono: contacto.whatsapp_phone || contacto.phone,
    texto: contacto.last_input_text,
    bot_activo: contacto.custom_fields?.bot_activo,
    ultima_interaccion: contacto.last_interaction,
    ...Object.fromEntries(Object.entries(crudo).filter(([k, v]) => k !== 'contacto' && v !== '' && v !== null && v !== undefined)),
  }
  : crudo;

// ManyChat deja "{{...}}" o vacío cuando una variable no tiene valor
function valor(v) {
  if (v === undefined || v === null) return '';
  const s = String(v).trim();
  if (/^\{\{[^}]*\}\}$/.test(s)) return '';
  return s;
}

const EXT_AUDIO = /\.(ogg|oga|opus|mp3|m4a|aac|amr|wav|weba|mpeg)(\?|#|$)/i;
const EXT_IMAGEN = /\.(jpe?g|png|webp|gif|heic)(\?|#|$)/i;
const HOST_MEDIA = /(manychat|manybot|fbsbx|fbcdn|whatsapp|amazonaws)\./i;
const esUrl = (s) => /^https?:\/\/\S+$/i.test(s);

const subscriberId = valor(body.subscriber_id ?? body.contact_id);
let texto = valor(body.texto ?? body.last_input_text);
let adjuntoUrl = valor(body.adjunto_url);
const tipoDeclarado = valor(body.tipo).toLowerCase();

// En WhatsApp, ManyChat guarda la URL del audio o la foto en "Last Text Input"
if (!adjuntoUrl && esUrl(texto) && (EXT_AUDIO.test(texto) || EXT_IMAGEN.test(texto) || HOST_MEDIA.test(texto))) {
  adjuntoUrl = texto;
  texto = '';
}
if (adjuntoUrl && !esUrl(adjuntoUrl)) adjuntoUrl = '';

// Tipo probable; el definitivo sale del archivo descargado ("Preparar archivo")
let tipoProbable = 'texto';
if (adjuntoUrl) {
  if (['audio', 'voz', 'voice'].includes(tipoDeclarado) || EXT_AUDIO.test(adjuntoUrl)) tipoProbable = 'audio';
  else if (['imagen', 'image', 'foto'].includes(tipoDeclarado) || EXT_IMAGEN.test(adjuntoUrl)) tipoProbable = 'imagen';
  else tipoProbable = 'otro';
}

// bot_activo vacío (contacto nuevo) cuenta como activo
const botRaw = valor(body.bot_activo).toLowerCase();
const botActivo = !['no', 'false', '0', 'off', 'n'].includes(botRaw);

// Clave de idempotencia: mismo contacto + misma interacción + mismo contenido.
// Si ManyChat reintenta el webhook, la segunda llamada da la misma clave.
function fnv1a(str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
const huella = [subscriberId, valor(body.ultima_interaccion), texto, adjuntoUrl].join('|');
const claveIdempotencia = `otormin:dedupe:${subscriberId}:${fnv1a(huella, 2166136261)}${fnv1a(huella, 33554467)}`;

const nombre = [valor(body.nombre), valor(body.apellido)].filter(Boolean).join(' ');

return [{
  json: {
    valido: subscriberId !== '',
    subscriber_id: subscriberId,
    nombre,
    telefono: valor(body.telefono),
    texto,
    adjunto_url: adjuntoUrl,
    tipo_probable: tipoProbable,
    bot_activo: botActivo,
    clave_idempotencia: claveIdempotencia,
    clave_buffer: `otormin:buffer:${subscriberId}`,
    texto_log: texto || (adjuntoUrl ? `[${tipoProbable}] ${adjuntoUrl}` : ''),
  },
}];

// Define si el adjunto es audio, imagen u otra cosa según el archivo descargado,
// y le pone un nombre con extensión válida (Whisper lo necesita).
const item = $input.first();
const bin = item.binary?.data;
const datos = $('Normalizar entrada').first().json;

if (!bin) {
  return [{ json: { tipo_archivo: 'otro', mime: '' } }];
}

const nombre = String(bin.fileName || '');
const ext = (nombre.match(/\.([a-z0-9]+)$/i)?.[1] || '').toLowerCase();
let mime = String(bin.mimeType || '').toLowerCase().split(';')[0].trim();

const MIME_POR_EXT = {
  ogg: 'audio/ogg', oga: 'audio/ogg', opus: 'audio/ogg', mp3: 'audio/mpeg', m4a: 'audio/mp4',
  aac: 'audio/aac', wav: 'audio/wav', amr: 'audio/amr',
  jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif',
};
const sinTipo = () => !mime || mime === 'application/octet-stream' || mime === 'binary/octet-stream';
if (sinTipo() && MIME_POR_EXT[ext]) mime = MIME_POR_EXT[ext];
if (sinTipo() && datos.tipo_probable === 'audio') mime = 'audio/ogg';
if (sinTipo() && datos.tipo_probable === 'imagen') mime = 'image/jpeg';
if (mime === 'video/ogg') mime = 'audio/ogg'; // notas de voz que llegan como video/ogg

let tipo = 'otro';
if (mime.startsWith('audio/')) tipo = 'audio';
else if (mime.startsWith('image/')) tipo = 'imagen';

const EXT_POR_MIME = {
  'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3', 'audio/mp4': 'm4a',
  'audio/aac': 'm4a', 'audio/x-m4a': 'm4a', 'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/webm': 'webm',
  'audio/amr': 'amr', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
};
const extFinal = EXT_POR_MIME[mime] || ext || 'bin';
bin.mimeType = mime || 'application/octet-stream';
bin.fileName = `${tipo === 'audio' ? 'audio' : 'archivo'}.${extFinal}`;
bin.fileExtension = extFinal;

return [{ json: { tipo_archivo: tipo, mime }, binary: { data: bin } }];

// Saca el texto (JSON) que devolvió el análisis de imagen y lo deja listo para el agente
const r = $input.first().json;
const partes = Object.values(r || {});
const mensaje = partes.find((p) => p && p.type === 'message') || r['0'] || r;
let analisis = mensaje?.content?.[0]?.text ?? r.content?.[0]?.text ?? r.text ?? '';
analisis = String(analisis).replace(/```json|```/g, '').trim();

const contenido = analisis
  ? `[Imagen del cliente] Análisis automático de la foto (JSON): ${analisis}`
  : '[El cliente mandó una foto que no se pudo analizar. Pedile que te cuente qué auto es o qué necesita.]';

return [{ json: { contenido } }];

// Junta el texto del cliente con lo que salió del audio o la foto,
// y arma el payload único que va al buffer de Redis (igual que el demo).
const datos = $('Normalizar entrada').first().json;
const extra = String($input.first().json.contenido || '').trim();
const contenido = [datos.texto, extra].filter((s) => s && String(s).trim()).join('\n')
  || '[el cliente envió un contenido que no puedo interpretar]';

return [{
  json: {
    contenido,
    mensaje_payload: `${Date.now()}-${Math.floor(Math.random() * 1e6)}|${contenido}`,
  },
}];

// query trae: precio_usd, anticipo_pct, cuotas
// La tasa, el anticipo mínimo y los plazos salen del nodo "Configuración Otormín".
const cfg = $('Configuración Otormín').first().json;
const num = (v) => {
  const s = String(v ?? '').replace('%', '').replace(',', '.').trim();
  if (s === '') return NaN;
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
};

const tasaAnualPct = num(cfg.TASA_FINANCIACION);
const anticipoMinPct = num(cfg.ANTICIPO_MINIMO);
if (Number.isNaN(tasaAnualPct) || Number.isNaN(anticipoMinPct) || tasaAnualPct < 0 || anticipoMinPct < 0 || anticipoMinPct > 100) {
  return JSON.stringify({
    error: 'financiacion_no_configurada',
    mensaje: 'La tasa o el anticipo mínimo todavía no están cargados. No des números: decile al cliente que un asesor le pasa la propuesta de financiación y usá pedir_humano.',
  });
}

const permitidas = String(cfg.CUOTAS_PERMITIDAS || '12,24,36,48,60')
  .split(',').map(num).filter((n) => n > 0);

const precio = num(query.precio_usd);
if (!(precio > 0)) {
  return 'Error: falta el precio del vehiculo en USD.';
}

let pct = num(query.anticipo_pct);
if (Number.isNaN(pct)) pct = anticipoMinPct;
const anticipoAjustado = pct < anticipoMinPct;
if (pct < anticipoMinPct) pct = anticipoMinPct;
if (pct > 100) pct = 100;

let n = num(query.cuotas);
if (Number.isNaN(n)) n = permitidas.includes(36) ? 36 : permitidas[0];
if (!permitidas.includes(n)) {
  n = permitidas.reduce((a, b) => (Math.abs(b - n) < Math.abs(a - n) ? b : a));
}

const anticipo = Math.round(precio * pct / 100);
const aFinanciar = precio - anticipo;
if (aFinanciar <= 0) {
  return JSON.stringify({ precio_usd: precio, mensaje: 'Con ese anticipo es pago contado, no hay saldo a financiar.' });
}

const i = tasaAnualPct / 100 / 12;
const cuota = i === 0 ? aFinanciar / n : aFinanciar * i / (1 - Math.pow(1 + i, -n));
const total = anticipo + cuota * n;

return JSON.stringify({
  precio_usd: precio,
  anticipo_usd: anticipo,
  anticipo_pct: pct,
  anticipo_minimo_pct: anticipoMinPct,
  anticipo_ajustado_al_minimo: anticipoAjustado,
  monto_a_financiar_usd: aFinanciar,
  cuotas: n,
  cuota_mensual_usd: Math.round(cuota),
  total_a_pagar_usd: Math.round(total),
  tasa_anual_pct: tasaAnualPct,
  planes_disponibles: permitidas,
  aclaracion: 'Cuota estimada. La aprobacion final depende de la evaluacion crediticia.',
});

