// query trae: motivo, resumen, auto_interes
// Esta herramienta solo registra el pedido. Apenas el agente termina de responder,
// el workflow hace la derivación en este orden:
//   1) bot_activo = no   2) tag necesita_humano + motivo_derivacion
//   3) flow de ManyChat que avisa al equipo   4) mensaje al cliente
const cfg = $('Configuración Otormín').first().json;
const resumen = String(query?.resumen || '').trim();
const motivo = String(query?.motivo || '').trim();

if (!resumen && !motivo) {
  return 'Falta el resumen: decime en una frase qué quiere el cliente, qué auto y por qué lo derivás.';
}

return `Listo, el pedido quedó registrado y el equipo de ${cfg.NOMBRE_EMPRESA} recibe el aviso. ` +
  'En tu respuesta avisale al cliente que un asesor lo va a contactar enseguida y no sigas la venta vos. ' +
  'En el JSON poné "estado": "necesita_humano" y completá "motivo_derivacion".';

