// Parseo tolerante de la salida del agente (el mismo del demo) + estado,
// auto de interés y derivación a humano (herramienta pedir_humano).
const item = $input.first();
const ctx = $('Contexto del agente').first().json;
const cfg = $('Configuración Otormín').first().json;
const agentOutput = item.json.output || item.json.text || '';

let mensaje1 = '', mensaje2 = '', mensaje3 = '';
let parsed = null;
let raw = String(agentOutput).replace(/```json|```/g, '').trim();

function extractFirstJSON(text) {
  const start = text.indexOf('{');
  if (start === -1) return null;
  let depth = 0, inString = false, escape = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (escape) { escape = false; continue; }
    if (ch === '\\') { escape = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) return text.substring(start, i + 1); }
  }
  return null;
}

function tryParseLenient(jsonStr) {
  try { return JSON.parse(jsonStr); } catch (_) {}
  try {
    let fixed = '';
    let inStr = false, esc = false;
    for (let i = 0; i < jsonStr.length; i++) {
      const ch = jsonStr[i];
      if (esc) { fixed += ch; esc = false; continue; }
      if (ch === '\\') { fixed += ch; esc = true; continue; }
      if (ch === '"') { inStr = !inStr; fixed += ch; continue; }
      if (inStr && ch === '\n') { fixed += '\\n'; continue; }
      if (inStr && ch === '\r') { fixed += '\\r'; continue; }
      if (inStr && ch === '\t') { fixed += '\\t'; continue; }
      fixed += ch;
    }
    return JSON.parse(fixed);
  } catch (_) { return null; }
}

const firstJson = extractFirstJSON(raw);
if (firstJson) {
  parsed = tryParseLenient(firstJson);
  if (parsed) {
    mensaje1 = parsed.mensaje1 || '';
    mensaje2 = parsed.mensaje2 || '';
    mensaje3 = parsed.mensaje3 || '';
  } else { mensaje1 = raw; }
} else { mensaje1 = raw; }

if (mensaje1 && typeof mensaje1 === 'string' && mensaje1.includes('"mensaje1"')) {
  const innerJson = extractFirstJSON(mensaje1);
  if (innerJson) {
    const parsed2 = tryParseLenient(innerJson);
    if (parsed2) {
      parsed = { ...(parsed || {}), ...parsed2 };
      mensaje1 = parsed2.mensaje1 || mensaje1;
      mensaje2 = parsed2.mensaje2 || mensaje2;
      mensaje3 = parsed2.mensaje3 || mensaje3;
    }
  }
}

function toCleanText(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v.trim();
  if (Array.isArray(v)) return v.map(toCleanText).filter(Boolean).join('\n').trim();
  if (typeof v === 'object') { try { return JSON.stringify(v); } catch (_) { return ''; } }
  return String(v).trim();
}

mensaje1 = toCleanText(mensaje1);
mensaje2 = toCleanText(mensaje2);
mensaje3 = toCleanText(mensaje3);

const fotos = [];
function agregarFoto(url) {
  if (fotos.length < 3 && !fotos.includes(url)) fotos.push(url);
}

// Saca las lineas "FOTO: <url>" (y las URLs sueltas) del texto y las
// junta aparte para mandarlas como fotos reales al final.
function extraerFotos(s) {
  if (!s) return '';
  return s.split('\n').filter((line) => {
    const t = line.trim();
    if (!t) return false;
    const m = t.match(/^FOTO:\s*(https?:\/\/\S+)$/i);
    if (m) { agregarFoto(m[1]); return false; }
    if (/^https?:\/\/\S+$/i.test(t)) { agregarFoto(t); return false; }
    return true;
  }).join('\n').trim();
}

mensaje1 = extraerFotos(mensaje1);
mensaje2 = extraerFotos(mensaje2);
mensaje3 = extraerFotos(mensaje3);

if (!mensaje1 && (mensaje2 || mensaje3)) {
  mensaje1 = mensaje2; mensaje2 = mensaje3; mensaje3 = '';
}
if (!mensaje1 && mensaje3) { mensaje1 = mensaje3; mensaje3 = ''; }

// ---------------- Herramientas usadas en este turno ----------------
const pasos = Array.isArray(item.json.intermediateSteps) ? item.json.intermediateSteps : [];
const llamadas = pasos.map((p) => {
  let args = p?.action?.toolInput ?? {};
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (_) { args = { resumen: args }; } }
  if (args && typeof args.input === 'object' && args.input !== null) args = args.input;
  return { tool: String(p?.action?.tool || ''), args: args || {}, resultado: String(p?.observation ?? '') };
});
const pedido = llamadas.filter((l) => l.tool === 'pedir_humano').pop();
const visitaOk = llamadas.some((l) => l.tool === 'agendar_visita' && l.resultado && !/error|invalid|fail|problem/i.test(l.resultado));

// ---------------- Estado de la conversación ----------------
const ESTADOS = ['nuevo', 'en_conversacion', 'lead_caliente', 'visita_agendada', 'necesita_humano', 'cerrada', 'sin_respuesta'];
const normalizar = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim().replace(/[\s-]+/g, '_');
let estado = normalizar(parsed?.estado);

const derivar = Boolean(pedido) || estado === 'necesita_humano';
if (derivar) estado = 'necesita_humano';
// visita_agendada solo si agendar_visita confirmó el turno (o ya estaba agendada)
if (estado === 'visita_agendada' && !visitaOk && ctx.estado_anterior !== 'visita_agendada') estado = 'lead_caliente';
if (!ESTADOS.includes(estado) || estado === 'sin_respuesta') {
  estado = ['en_conversacion', 'lead_caliente', 'visita_agendada'].includes(ctx.estado_anterior)
    ? ctx.estado_anterior
    : 'en_conversacion';
}
// primer contacto: queda en "nuevo" salvo que ya sea algo más fuerte
if (ctx.es_primer_contacto && estado === 'en_conversacion') estado = 'nuevo';

const recortar = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);
const autoInteres = recortar(parsed?.auto_interes || pedido?.args?.auto_interes, 200);

const MOTIVOS = {
  pedido_del_cliente: 'Pidió hablar con una persona',
  cliente_molesto: 'Cliente molesto o con un reclamo',
  permuta_o_tasacion: 'Permuta o tasación',
  legal_o_prenda: 'Tema legal o prenda',
  oferta_baja: 'Oferta por debajo del precio o pide descuento',
  lead_caliente: 'Lead caliente: quiere reservar, visitar o cerrar',
  tema_ajeno: 'Tema ajeno a la automotora',
  no_entiendo: 'El bot no entiende qué necesita',
  otro: 'Otro motivo',
};

let motivo = '';
if (derivar) {
  const codigo = String(pedido?.args?.motivo || '').trim();
  const partes = [MOTIVOS[codigo] || codigo, pedido?.args?.resumen, parsed?.motivo_derivacion]
    .map((s) => recortar(s, 300))
    .filter(Boolean);
  motivo = [...new Set(partes)].join(' | ') || 'El asesor virtual pidió ayuda humana.';
  if (autoInteres && !motivo.includes(autoInteres)) motivo = `${motivo} | Auto: ${autoInteres}`;
  motivo = recortar(motivo, 500);
}

if (!mensaje1) {
  mensaje1 = derivar
    ? `Te paso con un asesor de ${cfg.NOMBRE_EMPRESA}, te escribe enseguida.`
    : 'Disculpá, se me cortó la respuesta. ¿Me repetís lo último?';
}

return [{
  json: {
    origen: 'agente',
    subscriber_id: ctx.subscriber_id,
    mensaje1,
    mensaje2,
    mensaje3,
    fotos,
    estado,
    estado_anterior: ctx.estado_anterior,
    es_primer_contacto: ctx.es_primer_contacto,
    derivar,
    motivo_derivacion: motivo,
    auto_interes: autoInteres,
    herramientas_usadas: llamadas.map((l) => l.tool),
  },
}];

// El agente falló (OpenAI caído, timeout, etc.): el cliente nunca queda sin respuesta.
// Se le manda un mensaje amable y se deriva a un humano.
const ctx = $('Contexto del agente').first().json;
const cfg = $('Configuración Otormín').first().json;
const err = $input.first().json.error;
const detalle = typeof err === 'string' ? err : (err?.message || JSON.stringify(err || {}));

return [{
  json: {
    origen: 'respaldo',
    subscriber_id: ctx.subscriber_id,
    mensaje1: cfg.MENSAJE_RESPALDO,
    mensaje2: '',
    mensaje3: '',
    fotos: [],
    estado: 'necesita_humano',
    estado_anterior: ctx.estado_anterior,
    es_primer_contacto: ctx.es_primer_contacto,
    derivar: true,
    motivo_derivacion: `Falla técnica del asesor virtual, revisar el chat. Último mensaje del cliente: "${String(ctx.mensaje || '').replace(/\s+/g, ' ').slice(0, 250)}"`,
    auto_interes: '',
    error: String(detalle).slice(0, 300),
  },
}];

// Junta la respuesta (del agente o de respaldo) con el estado real del contacto en
// ManyChat, y arma lo que hay que guardar: campos, tags y flows.
const fuente = $('Interpretar respuesta del agente').isExecuted
  ? 'Interpretar respuesta del agente'
  : 'Armar respuesta de respaldo';
const r = $(fuente).first().json;
const cfg = $('Configuración Otormín').first().json;
const info = $input.first().json || {};

const ESTADOS = ['nuevo', 'en_conversacion', 'lead_caliente', 'visita_agendada', 'necesita_humano', 'cerrada', 'sin_respuesta'];
const configurado = (v) => Boolean(v) && !/COMPLETAR/i.test(String(v));

// ¿Un humano apagó el bot mientras el agente pensaba? (si ManyChat no responde, se asume activo)
const campos = Array.isArray(info.data?.custom_fields) ? info.data.custom_fields : [];
const campoBot = campos.find((c) => c && c.name === 'bot_activo');
const valorBot = String(campoBot?.value ?? '').trim().toLowerCase();
const botActivoAhora = !['no', 'false', '0', 'off', 'n'].includes(valorBot);

// Campos de ManyChat (bot_activo va aparte, primero, en "Apagar bot")
const camposManychat = [{ field_name: 'estado_conversacion', field_value: r.estado }];
if (r.derivar) camposManychat.push({ field_name: 'motivo_derivacion', field_value: r.motivo_derivacion });
if (r.auto_interes) camposManychat.push({ field_name: 'auto_interes', field_value: r.auto_interes });

const cambioEstado = r.estado !== r.estado_anterior || Boolean(r.es_primer_contacto);
const tagQuitar = r.estado !== r.estado_anterior && ESTADOS.includes(r.estado_anterior) ? r.estado_anterior : '';

// ManyChat espera el subscriber_id numérico; si es muy largo se manda como texto para no perder dígitos
const sid = String(r.subscriber_id);
const subscriberIdApi = /^\d{1,15}$/.test(sid) ? Number(sid) : sid;

return [{
  json: {
    ...r,
    subscriber_id_api: subscriberIdApi,
    bot_activo_ahora: botActivoAhora,
    campos_manychat: camposManychat,
    cambio_estado: cambioEstado,
    tag_quitar: tagQuitar,
    tag_poner: r.estado,
    notificar_equipo: Boolean(r.derivar) && configurado(cfg.FLOW_NOTIFICAR_HUMANO),
    cerrar_conversacion: r.estado === 'cerrada' && configurado(cfg.FLOW_CERRAR_CONVERSACION),
    texto_enviado: [r.mensaje1, r.mensaje2, r.mensaje3].filter(Boolean).join('\n\n'),
  },
}];

// Una salida por foto (máximo 3). Si no hay fotos no sale nada y el workflow termina.
const r = $('Preparar envío').first().json;
return (r.fotos || []).slice(0, 3).map((url) => ({
  json: { url, subscriber_id_api: r.subscriber_id_api },
}));
